<script setup>import{ref,reactive,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api}from'../api';const list=ref([]),dialog=ref(false),range=ref([]);const empty=()=>({id:null,title:'',image:'',targetType:'none',targetId:null,startAt:'',endAt:'',sort:0,status:1});let form=reactive(empty());const load=async()=>list.value=await api.activities();onMounted(load);function edit(x){Object.assign(form,empty(),JSON.parse(JSON.stringify(x)));range.value=x.id?[x.startAt,x.endAt]:[];dialog.value=true}async function save(){form.startAt=range.value[0];form.endAt=range.value[1];await api.saveActivity(form.id,form);ElMessage.success('活动已保存');dialog.value=false;load()}async function remove(x){await ElMessageBox.confirm(`删除活动「${x.title}」？`,'提示');await api.deleteActivity(x.id);load()}</script>
<template><div class="page-head"><div><h2>活动 Banner</h2><p>控制小程序首页轮播、跳转商品和展示时间</p></div><el-button type="primary" @click="edit(empty())">新增活动</el-button></div><div class="panel"><el-table :data="list"><el-table-column label="图片" width="110"><template #default="{row}"><img class="thumb" :src="row.image"/></template></el-table-column><el-table-column prop="title" label="活动标题"/><el-table-column label="展示时间" min-width="280"><template #default="{row}">{{row.startAt}} — {{row.endAt}}</template></el-table-column><el-table-column prop="targetId" label="目标商品"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status?'success':'info'">{{row.status?'上架':'下架'}}</el-tag></template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="form.id?'编辑活动':'新增活动'" width="620px"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="Banner 图片 URL"><el-input v-model="form.image"/></el-form-item><el-form-item label="展示时间"><el-date-picker v-model="range" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px"><el-form-item label="跳转类型"><el-select v-model="form.targetType" style="width:100%"><el-option label="不跳转" value="none"/><el-option label="卡商品" value="product"/></el-select></el-form-item><el-form-item label="商品 ID"><el-input-number v-model="form.targetId" :disabled="form.targetType!=='product'" style="width:100%"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort" style="width:100%"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
